            types.SimpleNamespace(
                stop_reason="tool_use",
                content=[tool_block("read_file", "read_1", path="note.txt")],
            ),
            types.SimpleNamespace(
                stop_reason="end_turn",
                content=[types.SimpleNamespace(type="text", text="The note says child input.")],
            ),
        ]

