    assert calls[0]["messages"] == [
        {"role": "user", "content": "Read note.txt and report its contents."}
    ]
    assert {tool["name"] for tool in calls[0]["tools"]} == {
        "bash", "read_file", "write_file", "edit_file", "glob",
    }
    assert result == "The note says child input."


